<script setup>
import MEmptyState from '../../../components/mds/MEmptyState.vue';
import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';
defineProps({ title: String, description: String, columns: { type: Array, default: () => [] }, rows: { type: Array, default: () => [] }, safeAreaStyle: Object }); const emit = defineEmits(['back']);
function value(row, column) { const raw=row?.[column.key]; if(column.money)return new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(raw||0));return raw===''||raw==null?'—':raw; }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="title" @back="emit('back')"/><main class="min-h-0 flex-1 overflow-y-auto pb-[var(--mds-mobile-safe-bottom)]"><div class="mds-mobile-gutter-x py-4"><p class="text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">{{ description }}</p><MEmptyState v-if="!rows.length" title="Chưa có dữ liệu trong kỳ" description="Thử đổi kỳ báo cáo hoặc kiểm tra lại quyền truy cập."/><div v-else class="mt-4 divide-y divide-[var(--mds-border-light)]"><article v-for="(row,index) in rows" :key="row.id || row.name || index" class="py-3"><dl class="space-y-2"><div v-for="column in columns" :key="column.key" class="grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-3"><dt class="text-[12px] text-[var(--mds-text-secondary)]">{{ column.label }}</dt><dd :class="['min-w-0 break-words text-right text-[13px]',column.money?'font-medium tabular-nums':'']">{{ value(row,column) }}</dd></div></dl></article></div></div></main></section></template>
